// ===== C0/9175 edge-clamp dispatcher (DP=$1D00). Carry SET from a body = BLOCKED (skip store). =====
// $2E/$30 = X/Y accumulator velocity (signed 8-bit); $32/$33 = applied velocity out.
// X register here = player actor index from $0197 (used as $1801+X / $1881+X, i.e. low byte of pos).
void clamp9175(u8* r) {
    r[0x1D32] = 0; r[0x1D33] = 0;
    int X = r[0x0197];                                  // 917B: LDA $0197; TAX  (hi byte cleared, TDC/XBA)
    if (r[0x1D2E] != 0) {                               // X axis
        int blocked = ((s8)r[0x1D2E] < 0)
            ? edge_LEFT (r, X)                          // 9185 -> 5B86
            : edge_RIGHT(r, X);                         // 918C -> 5B79
        if (!blocked) r[0x1D32] = r[0x1D2E];
    }
    if (r[0x1D30] != 0) {                               // Y axis
        int blocked = ((s8)r[0x1D30] < 0)
            ? edge_UP  (r, X)                           // 919B -> 5B71   (NOTE: vel<0 -> 5B71)
            : edge_DOWN(r, X);                          // 91A2 -> 5B63   (NOTE: vel>0 -> 5B63)
        if (!blocked) r[0x1D33] = r[0x1D30];
    }
}
// Each body returns 1 = BLOCKED (carry SET in ROM). posX=$1801+X, posY=$1881+X are 8-bit (low byte).
// $01D9 is an ABSOLUTE scratch byte ($7E:01D9), not DP-relative.
int edge_LEFT (const u8* r,int X){ return (u8)r[0x1D1A] >= (u8)r[0x1801+X]; }            // 5B86: CMP $1D1A vs posX
int edge_RIGHT(const u8* r,int X){ return (u8)r[0x1801+X] >= (u8)r[0x1D1B]; }            // 5B79: posX >= $1D1B
int edge_UP   (const u8* r,int X){ return (u8)(r[0x1D1C]+1) >= (u8)r[0x1881+X]; }        // 5B71: (u8)($1D1C+1) >= posY
int edge_DOWN (const u8* r,int X){ return (u8)r[0x1881+X] >= (u8)(r[0x1D1D]+1); }        // 5B63: posY >= (u8)($1D1D+1)

// ===== C0/5B95 actor-vs-actor "movability" test (DP=$0100). Returns 1 = BLOCKED (carry SET). =====
// CALLER (verified in trace): C0/5170 -> if blocked: $EE = (u8)($EE + 0x30); then always issues the step.
// (Also called from 4FBD,504F,50FC,51F4,5293,5329,53DC,54C8 -- multiple callers, not just one.)
// INDEX-STRIDE WARNING (UNRESOLVED): the scan X below is count*2 (word stride) and is compared CPX $6D;
//   this conflicts with field_tick.md's 0x80-stride for these same tables. Treat the per-actor indexing
//   as PROVISIONAL until pinned with a trace where $1C80,X&2 is set.
int actorMovable_5B95(u8* r) {
    r[0x01EA] = 0;                                      // 5B95 STZ $EA (absolute scratch)
    int Xm = r[0x006D];                                 // 5B97 LDX $6D = mover index
    if (r[0x0F00+Xm] == 0) return 0;                    // 5B99 not active -> CLC RTS (movable)
    if ((r[0x1C80+Xm] & 0x02) == 0) return 0;           // 5BA0/5BA3 gate clear -> CLC RTS (movable) [trace path]
    save_Y_into(0x01C7);                                // 5BA7 STY $C7
    r[0x00D9] = (u8)(r[0x1600+Xm] << 1);               // 5BA9 facing*2 -> jump index ($D9, DP=$01D9)
    u16 moverX = rd16(r,0x1800+Xm);  r16(0x01DB)=moverX;// 5BB1 (REP#20) mover X
    u16 moverY = rd16(r,0x1880+Xm);  r16(0x01DD)=moverY;// 5BB6 mover Y
    int X = ((int)r[0x7F2000]) << 1;                    // 5BBD count*2  (DEX DEX scan; stop at X==0)
    while (X != 0) {
        if (r[0x0F00+X] != 0) {                         // 5BC3 candidate active?
            if ((r[0x1100+X] & 0x80) == 0 &&            // 5BD2 BMI skip if dead/inactive
                X != Xm &&                              // 5BD7 CPX $6D : skip self
                (r[0x1B01+X] & 0x01) != 0) {            // 5BDB solid?
                r[0x00E9] = X;                          // 5BE2 STX $E9 (save candidate)
                // 5BE6 JSR ($5BF2 + facing*2): box handler. CARRY-IN IS UNINITIALIZED here -- model it.
                int blocked = boxTest[r[0x1600+Xm]](r); // {5BFA,5C20,5C47,5C6D}, carry-out: SET=blocked
                if (blocked) { restore_Y(0x01C7); return 1; }   // 5BEB BCS-> blocked SEC RTS
            }
        }
        X -= 2;                                         // 5BC8 DEX DEX
    }
    restore_Y(0x01C7); return 0;                        // 5BD0/5BF1 fall-through CLC RTS (movable)
}
// Box handlers (16-bit, REP #$20). |dY|<$0100 AND |dX|<$0100 (and correct sign per facing) => blocked.
// Negative branch uses EOR #$FFFF (one's-complement, NOT negate) before CMP #$0100 / BCS->reject.
// e.g. 5BFA (facing 0): dY = candY($1880+E9) -SBC- $DD; if BPL reject; else EOR#$FFFF; if dY>=$0100 reject;
//      dX = candX($1800+E9) -SBC- $DB; if BPL keep else EOR#$FFFF; if dX>=$0100 reject; else SEC(blocked).
//      First SBC at 5C01 has NO preceding SEC/CLC -> carry-in from JSR-entry must be modeled, not assumed.

// ===== C0/5B8D sign-of-$EB predicate (DP=$0100; caller C0/304F). =====
int signEB_5B8D(const u8* r){ return (r[0x00EB] & 0x80) ? 1 /*SEC*/ : 0 /*CLC*/; }
